/* Machines for the closure and regular-expression notes (Hakim Sir, Lecture 5), all generated by the constructions in lib/automata. */
import {
  complementDfa,
  concatNfa,
  faAccepts,
  productDfa,
  regexToNfa,
  reverseNfa,
  starNfa,
  starWithoutNewStart,
  swapAccept,
  unionNfa,
  type FA,
} from "@/lib/automata"
import { dfa } from "./notes-dfa"
import { nfa } from "./notes-nfa"
import type { Check } from "./types"

const count = (w: string, c: string) => [...w].filter((x) => x === c).length
const B = ["0", "1"]

/** N1: strings ending in 0. */
export const endsIn0 = dfa("p0", ["p1"], { p0: { 0: "p1", 1: "p0" }, p1: { 0: "p1", 1: "p0" } })
/** N2: strings of even length. */
export const evenLen = dfa("r0", ["r0"], { r0: { 0: "r1", 1: "r1" }, r1: { 0: "r0", 1: "r0" } })

export const unionEx = unionNfa(endsIn0, evenLen)
export const concatEx = concatNfa(endsIn0, evenLen)
export const starEx = starNfa(endsIn0)

/** The slides' complement example: strings ending in 0, states q0/q1. */
export const endsIn0q = dfa("q0", ["q1"], { q0: { 0: "q1", 1: "q0" }, q1: { 0: "q1", 1: "q0" } })
export const complementEx = complementDfa(endsIn0q)

export const productEx = productDfa(endsIn0, evenLen, "and")

/** For reversal: strings starting with 01 (d = dead). */
export const startsWith01 = dfa("s0", ["s2"], {
  s0: { 0: "s1", 1: "d" },
  s1: { 0: "d", 1: "s2" },
  s2: { 0: "s2", 1: "s2" },
  d: { 0: "d", 1: "d" },
})
export const reverseEx = reverseNfa(startsWith01, "s")

/** Why the shortcut star fails: N1 recognises a*b, and its start state has a self-loop. */
export const aStarB = nfa(["q1", "q2"], "q1", ["q2"], [["q1", "a", "q1"], ["q1", "b", "q2"]], ["a", "b"])
export const hastyStar = starWithoutNewStart(aStarB)
export const properStar = starNfa(aStarB, "q0")

/** Why swapping accept states fails for an NFA: N accepts strings containing 1. */
export const contains1Nfa = nfa(["q0", "q1"], "q0", ["q1"], [["q0", "0,1", "q0"], ["q0", "1", "q1"], ["q1", "0,1", "q1"]], B)
export const contains1Swapped = swapAccept(contains1Nfa)

/** The slides' (ab ∪ a)* example, built by the basic-principles construction. */
export const abUnionAStar = regexToNfa("(ab∪a)*")

/** The slides' GNFA example: ε or binary multiples of 3, start state q0 accepting. */
export const div3Eps = dfa("q0", ["q0"], { q0: { 0: "q0", 1: "q1" }, q1: { 0: "q2", 1: "q0" }, q2: { 0: "q1", 1: "q2" } })

const div3 = (w: string) => w === "" || parseInt(w, 2) % 3 === 0
const endsIn = (w: string, s: string) => w.endsWith(s)
const sameAs = (ref: FA) => (w: string) => faAccepts(ref, w)

export const regularNoteChecks: Check[] = [
  { id: "note-cl-ends0", machine: endsIn0, dfa: true, alphabet: B, maxLen: 9, inL: (w) => endsIn(w, "0") },
  { id: "note-cl-evenlen", machine: evenLen, dfa: true, alphabet: B, maxLen: 9, inL: (w) => w.length % 2 === 0 },
  { id: "note-cl-union", machine: unionEx, alphabet: B, maxLen: 9, inL: (w) => endsIn(w, "0") || w.length % 2 === 0 },
  {
    id: "note-cl-concat",
    machine: concatEx,
    alphabet: B,
    maxLen: 9,
    inL: (w) => [...Array(w.length + 1).keys()].some((k) => endsIn(w.slice(0, k), "0") && (w.length - k) % 2 === 0),
  },
  { id: "note-cl-star", machine: starEx, alphabet: B, maxLen: 9, inL: (w) => w === "" || endsIn(w, "0") },
  { id: "note-cl-complement", machine: complementEx, dfa: true, alphabet: B, maxLen: 9, inL: (w) => !endsIn(w, "0") },
  { id: "note-cl-product", machine: productEx, dfa: true, alphabet: B, maxLen: 9, inL: (w) => endsIn(w, "0") && w.length % 2 === 0 },
  { id: "note-cl-starts01", machine: startsWith01, dfa: true, alphabet: B, maxLen: 9, inL: (w) => w.startsWith("01") },
  { id: "note-cl-reverse", machine: reverseEx, alphabet: B, maxLen: 9, inL: (w) => endsIn(w, "10") },
  { id: "note-cl-astarb", machine: aStarB, alphabet: ["a", "b"], maxLen: 8, inL: (w) => /^a*b$/.test(w) },
  { id: "note-cl-proper-star", machine: properStar, alphabet: ["a", "b"], maxLen: 8, inL: (w) => /^(a*b)*$/.test(w) },
  // The shortcut accepts exactly (a*b)* plus strings ending in a's after a complete block: a, aa, ba, ...
  { id: "note-cl-hasty-star", machine: hastyStar, alphabet: ["a", "b"], maxLen: 8, inL: (w) => /^(a*b)*a*$/.test(w) },
  { id: "note-cl-contains1", machine: contains1Nfa, alphabet: B, maxLen: 8, inL: (w) => w.includes("1") },
  // Swapped NFA: q0 accepting, q0 loops on everything, so it accepts every string.
  { id: "note-cl-swapped", machine: contains1Swapped, alphabet: B, maxLen: 8, inL: () => true },
  { id: "note-re-ab-a-star-nfa", machine: abUnionAStar, alphabet: ["a", "b"], maxLen: 9, inL: (w) => /^(ab|a)*$/.test(w) },
  { id: "note-re-div3-dfa", machine: div3Eps, dfa: true, alphabet: B, maxLen: 12, inL: div3 },
  { id: "note-re-div3-regex", regex: "(0∪1(01*0)*1)*", alphabet: B, maxLen: 12, inL: div3 },
  { id: "note-re-ex1", regex: "0*10*", alphabet: B, maxLen: 9, inL: (w) => count(w, "1") === 1 },
  { id: "note-re-ex2", regex: "(0∪1)*1(0∪1)*", alphabet: B, maxLen: 9, inL: (w) => w.includes("1") },
  { id: "note-re-ex5", regex: "(0∪1)*1(0∪1)*1(0∪1)*", alphabet: B, maxLen: 9, inL: (w) => count(w, "1") >= 2 },
  { id: "note-re-ends00", regex: "(0∪1)*00", alphabet: B, maxLen: 9, inL: (w) => endsIn(w, "00") },
  { id: "note-re-even", regex: "((0∪1)(0∪1))*", alphabet: B, maxLen: 9, inL: (w) => w.length % 2 === 0 },
  { id: "note-re-ends1-a", regex: "(0∪1)*1", alphabet: B, maxLen: 9, inL: (w) => endsIn(w, "1") },
  { id: "note-re-ends1-b", regex: "0*1(1∪0⁺1)*", alphabet: B, maxLen: 9, inL: (w) => endsIn(w, "1") },
  { id: "note-re-ex-intro", regex: "(0∪1)0*", alphabet: B, maxLen: 9, inL: (w) => /^[01]0*$/.test(w) },
  { id: "note-re-same-as-dfa", machine: div3Eps, alphabet: B, maxLen: 6, inL: sameAs(div3Eps) },
  { id: "note-re-odd", regex: "(0∪1)((0∪1)(0∪1))*", alphabet: B, maxLen: 9, inL: (w) => w.length % 2 === 1 },
  { id: "note-re-two-a", regex: "b*ab*ab*", alphabet: ["a", "b"], maxLen: 9, inL: (w) => count(w, "a") === 2 },
  { id: "note-re-atmost-two-a", regex: "b*(a∪ε)b*(a∪ε)b*", alphabet: ["a", "b"], maxLen: 9, inL: (w) => count(w, "a") <= 2 },
  { id: "note-re-a-div3-1", regex: "(b*ab*ab*ab*)*b*", alphabet: ["a", "b"], maxLen: 10, inL: (w) => count(w, "a") % 3 === 0 },
  { id: "note-re-a-div3-2", regex: "b*(ab*ab*ab*)*", alphabet: ["a", "b"], maxLen: 10, inL: (w) => count(w, "a") % 3 === 0 },
  { id: "note-re-ends1-c", regex: "(0∪1)*1", alphabet: B, maxLen: 9, inL: (w) => endsIn(w, "1") },
  { id: "note-re-ident-star-union", regex: "(a*b*)*", alphabet: ["a", "b"], maxLen: 8, inL: () => true },
  { id: "note-re-nonident", regex: "a*∪b*", alphabet: ["a", "b"], maxLen: 8, inL: (w) => !w.includes("a") || !w.includes("b") },
]
